}

fn emit_module_output(output: &ProgramModuleOutput, format: OutputFormat) -> Result<()> {
    match format {
        OutputFormat::Text => {
            println!("program.module.cid {}", output.cid);
            println!("program.module.name {}", output.name);
            println!("program.module.entry {}", output.entry);
            println!("refs {}", output.refs.len());
        }
        OutputFormat::Json => print_json(output)?,
    }
    Ok(())
}
fn emit_module_eval_output(output: &ProgramModuleEvalOutput, format: OutputFormat) -> Result<()> {
    match format {
        OutputFormat::Text => {
            println!("program.module.eval status={}", output.status);
            println!("program.module.cid {}", output.module_cid);
            println!("program.module.entry {}", output.entry);
            println!("entry.program.cid {}", output.entry_program_cid);
            println!("result.cid {}", output.eval.result_cid);
        }
        OutputFormat::Json => print_json(output)?,
    }
    Ok(())
}
fn required_text_value<'a>(value: &'a Value, field: &str) -> Result<&'a str> {
    let text =
        value_text_field(value, field).ok_or_else(|| anyhow::anyhow!("{field} must be text"))?;
    if text.is_empty() {
        bail!("{field} must not be empty");
    }
    Ok(text)
}
fn required_string<'a>(object: &'a JsonMap<String, JsonValue>, key: &str) -> Result<&'a str> {
    let value = optional_string(object, key).ok_or_else(|| anyhow::anyhow!("{key} is required"))?;
    if value.is_empty() {
        bail!("{key} must not be empty");
    }
    Ok(value)
}
fn optional_string<'a>(object: &'a JsonMap<String, JsonValue>, key: &str) -> Option<&'a str> {
    object.get(key)?.as_str()
}

